create or replace function public.request_organization_export_async(p_organization_id uuid, p_from timestamptz default now() - interval '180 days', p_to timestamptz default now()) returns uuid language plpgsql security definer set search_path = 'public', 'pg_catalog' as $$ declare v_request_id uuid; begin if not public.has_org_role(p_organization_id, array['SUPER_ADMIN','ORGANIZATION_ADMIN']) then raise exception 'Not authorized'; end if; if p_from >= p_to then raise exception 'Invalid export time range'; end if; insert into public.privacy_requests (organization_id, requested_by, request_type, status, metadata) values (p_organization_id, auth.uid(), 'EXPORT', 'PENDING', jsonb_build_object('async', true, 'from', p_from, 'to', p_to)) returning id into v_request_id; return v_request_id; end; $$;